    @Test func vectorResizingFromUInt8() {
        let mismatches = Mismatches("portVectorResizingU8ToI32InVectorCode")
        let aInputs = Inputs.conversions(SIMD<UInt8>.self, seed: 0xCFA9_C7BF_307C_F001)
        for a in aInputs {
            let port = { () -> SIMD<Int32> in
                var a = a
                return withUnsafeTemporaryAllocation(of: SIMD<Int32>.self, capacity: 1) { result in
                    unsafe portVectorResizingU8ToI32InVectorCode(
                        result.baseAddress.unsafelyUnwrapped,
                        resizing: &a
                    )
                    return unsafe result.baseAddress.unsafelyUnwrapped.move()
                }
            }()
            let reference = { () -> SIMD<Int32> in
                var a = a
                return withUnsafeTemporaryAllocation(of: SIMD<Int32>.self, capacity: 1) { result in
                    unsafe highwayVectorResizingU8ToI32InVectorCode(
                        result.baseAddress.unsafelyUnwrapped,
                        resizing: &a
                    )
                    return unsafe result.baseAddress.unsafelyUnwrapped.move()
                }
            }()
            let definedBytes = SIMD<UInt8>.laneCount * MemoryLayout<UInt8>.stride
            let grownBytes = H.laneCount * MemoryLayout<Lane>.stride
            let newBytes = HighwayReference.resizedBytesDefined(
                definedBytes,
                grownBytes,
                definedBytes
            )
            mismatches.check(
                Array(bytes(of: port).prefix(definedBytes)),
                Array(bytes(of: reference).prefix(definedBytes)),
                "a: \(describe(a))"
